def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    lm = me[-1]
    lo = opp[-1]

    opp_d = opp.count('D')
    me_d = me.count('D')

    r5 = sum(1 for x in opp[-5:] if x == 'D')
    r10 = sum(1 for x in opp[-10:] if x == 'D')

    dS = dP = cS = cP = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            if opp[i] == 'C':
                dS += 1
            else:
                dP += 1
        else:
            if opp[i] == 'C':
                cS += 1
            else:
                cP += 1

    td = dS + dP
    pD = (dS + 1.0) / (td + 2.0) if td else 0.35
    tc = cS + cP
    pC = (cS + 1.0) / (tc + 2.0) if tc else 0.75

    exploit = False
    if td >= 4 and pD >= 0.6 and pC - pD <= 0.25:
        exploit = True
    if dS >= 3 and dP == 0:
        exploit = True
    if exploit:
        return 'D'

    if lm == 'D' and lo == 'C' and dP == 0 and dS < 3 and n < 95:
        if opp_d <= max(8, n // 3) and r5 <= 2:
            return 'D'

    hostile = False
    if n >= 20 and (r5 >= 4 or r10 >= 7):
        hostile = True
    if n >= 30 and opp_d * 2 >= n:
        hostile = True
    if lm == 'D' and lo == 'D' and n >= 10 and r5 >= 3:
        hostile = True
    if tc >= 8 and cS * 2 <= cP and opp_d >= 8:
        hostile = True
    if hostile:
        return 'D'

    if (me_d == 0 and lm == 'C' and lo == 'C' and n >= 40 and n <= 85
            and r5 == 0 and opp_d >= 2 and opp_d * 5 <= n
            and rng.random() < 0.03):
        return 'D'

    if n == 98:
        return 'C'

    if lo == 'D':
        return 'C'

    if lm == 'D':
        return 'C'

    return 'C'
